#section-1 .special-heading__subtitle{font-family:Inter, system-ui, -apple-system, sans-serif !important;font-size:14px !important;font-weight:400 !important;line-height:22.75px !important;color:rgb(203, 213, 225) !important;}
#section-1{padding-top:0px !important;padding-bottom:0px !important;}
